mapper.select:
SELECT id, user_name, password, nick_name, email, status, create_time, update_time
FROM `user`
WHERE user_name = #{userName}
AND password = #{password}
AND status = 1

mapper.update:
UPDATE `user`
user_name = #{userName}, password = #{password}, nick_name = #{nickName}, email = #{email}, status = #{status},
WHERE id = #{id}

